contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool expectPaused) public {
        bool before = c.paused();

        bool ok;
        bool ret;
        try c.paused() returns (bool v) {
            ok = true;
            ret = v;
        } catch {
            ok = false;
        }

        bool after = c.paused();

        assert(!ok || (ret == before && after == before));
    }
}

