contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address currentAdmin, address newLrtConfig) public payable {
        // Need an admin account to test the admin path; ensure that account
        // actually is c's admin by setting it through c's own machinery.
        bool setupReverted;
        try c.updateLRTConfig(currentAdmin) {
            setupReverted = false;
        } catch {
            setupReverted = true;
        }

        address old = address(c.lrtConfig());
        bool reverted;
        try c.updateLRTConfig(newLrtConfig) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address current = address(c.lrtConfig());

        assert(
            (reverted
                ? (newLrtConfig == address(0) || currentAdmin != address(this))
                : (newLrtConfig != address(0) && current == newLrtConfig))
        );
    }

    receive() external payable {}
}

