contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        address[] memory beforeQueue = c.getNodeDelegatorQueue();
        uint256 len = beforeQueue.length;

        address[] memory afterQueue = c.getNodeDelegatorQueue();

        bool sameLength = (afterQueue.length == len);
        bool sameElements = true;
        for (uint256 i = 0; i < len && i < afterQueue.length; i++) {
            if (beforeQueue[i] != afterQueue[i]) {
                sameElements = false;
                break;
            }
        }

        assert(sameLength && sameElements);
    }

    receive() external payable {}
}

