contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount) public payable {
        require(amount > 0, "amount must be positive");
        require(c.getRsETHAmountToMint(asset, 0) == 0, "zero amount should mint zero");

        uint256 rsethPrice = c.getRsETHAmountToMint(asset, 1);
        require(rsethPrice != 0, "rsETH price from one unit must be nonzero");

        uint256 limit = c.getAssetCurrentLimit(asset);
        require(limit != type(uint256).max, "limit must be finite for the bound to be meaningful");

        uint256 rsethAmount = c.getRsETHAmountToMint(asset, amount);
        uint256 totalSupply = c.totalSupply();

        assert(rsethAmount <= amount * limit && rsethAmount + totalSupply >= rsethAmount);
    }

    receive() external payable {}
}

