contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address a1, address a2) public {
        address[] memory addrs = new address[](2);
        addrs[0] = a1;
        addrs[1] = a2;

        bool reverted;
        try c.addNodeDelegatorContractToQueue(addrs) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            uint256 len = c.getNodeDelegatorQueue().length;
            if (len >= 2) {
                address[] memory q = c.getNodeDelegatorQueue();
                // after successful add, last two elements are a1 and a2 (order preserved)
                assert(q[len - 2] == a1 && q[len - 1] == a2);
            } else {
                assert(false);
            }
        } else {
            // if it reverted, it must be because a1 or a2 is zero
            assert(a1 == address(0) || a2 == address(0));
        }
    }
}

