contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 max, address[] calldata delegators) public payable {
        require(max <= 1000, "too many");
        require(delegators.length <= 100, "too many delegators");

        // Setup: fresh c already initialized by the test harness.
        uint256[] memory beforeLen = new uint256[](delegators.length);
        bool[] memory sawRevert = new bool[](delegators.length);

        for (uint256 i; i < delegators.length; ++i) {
            beforeLen[i] = c.nodeDelegatorQueue.length;

            // Deliver reverts never occur when caller is allowed by onlyLRTAdmin.
            // But a batch with many/zero addresses can revert due to maxNodeDelegatorCount
            // or ZeroAddressNotAllowed, so track it.
            bool reverted = false;
            try c.addNodeDelegatorContractToQueue(_slice(delegators, i, i + 1)) {
                reverted = false;
            } catch {
                reverted = true;
            }
            sawRevert[i] = reverted;
        }

        uint256 finalLen = c.nodeDelegatorQueue.length;
        uint256 maxCount = c.maxNodeDelegatorCount();

        // General rule: the batch update never exceeds maxNodeDelegatorCount and
        // never drops entries: final queue is at least the initial queue and at most maxCount.
        assert(finalLen >= beforeLen[beforeLen.length - 1] && finalLen <= maxCount);

        // Stronger general rule over all single-element additions: if an individual
        // addition did not revert, the queue length increased by exactly one.
        for (uint256 i; i < delegators.length; ++i) {
            if (!sawRevert[i]) {
                assert(finalLen >= beforeLen[i] + 1);
            }
        }
    }

    function _slice(
        address[] calldata arr,
        uint256 start,
        uint256 end
    ) private pure returns (address[] memory out) {
        out = new address[](end - start);
        for (uint256 i = start; i < end; ++i) {
            out[i - start] = arr[i];
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 maxCount, address delegator) public payable {
        require(maxCount <= 1000, "too many");
        require(delegator != address(0), "zero address");

        address[] memory one = new address[](1);
        one[0] = delegator;

        // Setup: set the cap through the admin-gated setter.
        c.updateMaxNodeDelegatorCount(maxCount);

        uint256 beforeLen = c.getNodeDelegatorQueue().length;
        uint256 cap = c.maxNodeDelegatorCount();

        bool reverted;
        try c.addNodeDelegatorContractToQueue(one) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterLen = c.getNodeDelegatorQueue().length;

        if (beforeLen < cap) {
            // Capacity available: the non-zero address must be appended.
            assert(!reverted && afterLen == beforeLen + 1 && c.getNodeDelegatorQueue()[beforeLen] == delegator);
        } else {
            // Already at capacity: the batch must revert and leave the queue unchanged.
            assert(reverted && afterLen == beforeLen);
        }
    }

    receive() external payable {}
}

