    }

    function run(address[] calldata nodes) public payable {
        uint256 initialCount = c.getNodeDelegatorQueue().length;
        if (nodes.length > 0) {
            c.addNodeDelegatorContractToQueue(nodes);
        }
        uint256 afterCount = c.getNodeDelegatorQueue().length;
        address[] memory queue = c.getNodeDelegatorQueue();

        assert(afterCount == initialCount + nodes.length);
        assert(queue.length == afterCount);
        for (uint256 i = 0; i < nodes.length; i++) {
            assert(queue[initialCount + i] == nodes[i]);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata nodes) public payable {
        require(nodes.length > 0, "need at least one node");
        for (uint256 i = 0; i < nodes.length; i++) {
            require(nodes[i] != address(0), "zero address");
        }
        uint256 initialCount = c.getNodeDelegatorQueue().length;
        c.addNodeDelegatorContractToQueue(nodes);
        uint256 afterCount = c.getNodeDelegatorQueue().length;
        address[] memory queue = c.getNodeDelegatorQueue();
        assert(
            afterCount == initialCount + nodes.length
            && queue.length == afterCount
            && afterCount >= nodes.length
            && queue[initialCount] == nodes[0]
            && queue[afterCount - 1] == nodes[nodes.length - 1]
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address node) public payable {
        require(node != address(0), "zero address");
        uint256 before = c.getNodeDelegatorQueue().length;
        c.addNodeDelegatorContractToQueue(_toArr(node));
        address[] memory q = c.getNodeDelegatorQueue();
        assert(q.length == before + 1 && q[before] == node);
    }

    function _toArr(address node) private pure returns (address[] memory a) {
        a = new address[](1);
        a[0] = node;
    }

    receive() external payable {}
}

